package ru.magral.kupon;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.Bundle;
import android.text.Editable;
import android.text.InputType;
import android.text.TextWatcher;
import android.view.Gravity;
import android.view.View;
import android.view.inputmethod.EditorInfo;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.CheckBox;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.Toast;
import org.json.JSONArray;
import org.json.JSONObject;
import java.text.NumberFormat;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.Locale;

public class MainActivity extends Activity {
    private static final int GREEN=Color.rgb(28,105,67), PALE=Color.rgb(233,244,236), INK=Color.rgb(25,37,30), MUTED=Color.rgb(101,115,106), BG=Color.rgb(245,248,244);
    private final ArrayList<Product> products=new ArrayList<>(); private final ArrayList<Offer> offers=new ArrayList<>();
    private SharedPreferences prefs; private LinearLayout productList,offerList,results; private EditText cityInput,lentaDelivery,yarcheDelivery,productName,lentaPrice,yarchePrice,productQty,offerName,offerValue,offerMinimum,offerExpiry,offerSource; private Spinner offerStore,offerType; private CheckBox offerStackable; private boolean building; private String city="Барнаул";

    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);prefs=getSharedPreferences("kupon",MODE_PRIVATE);load();build();}
    private void load(){city=prefs.getString("city","Барнаул");try{JSONArray a=new JSONArray(prefs.getString("products","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);products.add(new Product(o.getString("name"),num(o,"lenta"),num(o,"yarche"),o.optInt("qty",1)));}a=new JSONArray(prefs.getString("offers","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);offers.add(new Offer(o.optString("store"),o.optString("type"),o.optString("name"),o.optDouble("value"),o.optDouble("minimum"),o.optString("expiry"),o.optString("source"),o.optBoolean("stack")));}}catch(Exception e){products.clear();offers.clear();}}
    private Double num(JSONObject o,String k){return o.isNull(k)?null:o.optDouble(k);}
    private void save(){try{JSONArray ps=new JSONArray(),os=new JSONArray();for(Product p:products){JSONObject o=new JSONObject();o.put("name",p.name);o.put("lenta",p.lenta);o.put("yarche",p.yarche);o.put("qty",p.qty);ps.put(o);}for(Offer x:offers){JSONObject o=new JSONObject();o.put("store",x.store);o.put("type",x.type);o.put("name",x.name);o.put("value",x.value);o.put("minimum",x.minimum);o.put("expiry",x.expiry);o.put("source",x.source);o.put("stack",x.stack);os.put(o);}prefs.edit().putString("city",cityInput==null?city:cityInput.getText().toString().trim()).putString("products",ps.toString()).putString("offers",os.toString()).putString("lenta_ship",lentaDelivery==null?"":lentaDelivery.getText().toString()).putString("yarche_ship",yarcheDelivery==null?"":yarcheDelivery.getText().toString()).apply();}catch(Exception ignored){}}

    private void build(){building=true;ScrollView scroll=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(16),dp(18),dp(16),dp(28));page.setBackgroundColor(BG);scroll.addView(page);setContentView(scroll);
        LinearLayout brand=row();TextView mark=label("₽",22,Color.WHITE,true);mark.setGravity(Gravity.CENTER);mark.setBackground(round(GREEN,14));LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(dp(46),dp(46));mp.rightMargin=dp(12);brand.addView(mark,mp);LinearLayout titles=new LinearLayout(this);titles.setOrientation(1);titles.addView(label("Корзина выгоднее",20,INK,true));titles.addView(label("Сравнение доставки и скидок",13,MUTED,false));brand.addView(titles);page.addView(brand);
        TextView intro=label("Где вся корзина выйдет дешевле — с учётом цен, промокодов и доставки?",17,INK,true);intro.setPadding(dp(16),dp(18),dp(16),dp(18));intro.setBackground(round(PALE,18));field(page,intro);
        section(page,"Ваш город");cityInput=input("Например, Барнаул",false);cityInput.setText(city);field(page,cityInput);
        section(page,"1. Состав заказа");productName=input("Название товара",false);field(page,productName);LinearLayout prices=row();lentaPrice=input("Лента ₽",true);yarchePrice=input("Ярче ₽",true);prices.addView(lentaPrice,weight());prices.addView(yarchePrice,weight());field(page,prices);productQty=input("Количество",true);productQty.setText("1");field(page,productQty);Button addP=button("＋ Добавить товар",true);field(page,addP);addP.setOnClickListener(v->addProduct());productList=new LinearLayout(this);productList.setOrientation(1);field(page,productList);
        section(page,"2. Акции и промокоды");LinearLayout selects=row();offerStore=spinner(new String[]{"Лента","Ярче!"});offerType=spinner(new String[]{"Скидка, %","Скидка, ₽","Бесплатная доставка"});selects.addView(offerStore,weight());selects.addView(offerType,weight());field(page,selects);offerName=input("Промокод или название акции",false);field(page,offerName);LinearLayout amounts=row();offerValue=input("Скидка",true);offerMinimum=input("Заказ от ₽",true);amounts.addView(offerValue,weight());amounts.addView(offerMinimum,weight());field(page,amounts);offerExpiry=input("Действует до, например 31.12.2026",false);field(page,offerExpiry);offerSource=input("Ссылка на условия (необязательно)",false);field(page,offerSource);offerStackable=new CheckBox(this);offerStackable.setText("Можно сочетать с другими скидками");offerStackable.setTextColor(INK);field(page,offerStackable);Button addO=button("＋ Добавить предложение",true);field(page,addO);addO.setOnClickListener(v->addOffer());offerList=new LinearLayout(this);offerList.setOrientation(1);field(page,offerList);
        section(page,"3. Итог с доставкой");TextView tip=label("Введите стоимость доставки, которую показывает приложение магазина. Акция на бесплатную доставку учитывается автоматически.",13,MUTED,false);field(page,tip);LinearLayout ship=row();lentaDelivery=input("Лента: доставка ₽",true);yarcheDelivery=input("Ярче!: доставка ₽",true);lentaDelivery.setText(prefs.getString("lenta_ship",""));yarcheDelivery.setText(prefs.getString("yarche_ship",""));ship.addView(lentaDelivery,weight());ship.addView(yarcheDelivery,weight());field(page,ship);results=new LinearLayout(this);results.setOrientation(1);field(page,results);
        Button official=button("Открыть официальные акции",false);field(page,official);official.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Официальные предложения").setItems(new String[]{"Акции и промокоды «Ленты»","Каталог «Ярче Плюс»"},(d,w)->open(w==0?"https://lenta.com/action/":"https://yarcheplus.ru/")).show());field(page,label("Коды и условия подтвердите на сайте или в приложении магазина перед заказом.",12,MUTED,false));
        TextWatcher watch=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!building){save();recalculate();}}public void afterTextChanged(Editable e){}};lentaDelivery.addTextChangedListener(watch);yarcheDelivery.addTextChangedListener(watch);cityInput.addTextChangedListener(watch);renderLists();recalculate();building=false;
    }
    private void addProduct(){String n=productName.getText().toString().trim();Double l=number(lentaPrice),y=number(yarchePrice);Double quantity=number(productQty);int q=Math.max(1,quantity==null?1:quantity.intValue());if(n.isEmpty()||(l==null&&y==null)){toast("Укажите название и цену хотя бы в одном магазине");return;}products.add(new Product(n,l,y,q));productName.setText("");lentaPrice.setText("");yarchePrice.setText("");productQty.setText("1");save();renderLists();recalculate();}
    private void addOffer(){String n=offerName.getText().toString().trim(),store=offerStore.getSelectedItemPosition()==0?"lenta":"yarche";int tp=offerType.getSelectedItemPosition();String type=tp==0?"percent":tp==1?"fixed":"delivery";Double val=number(offerValue),minimum=number(offerMinimum);if(n.isEmpty()){toast("Добавьте название акции или промокод");return;}if(!type.equals("delivery")&&(val==null||val<=0)){toast("Укажите размер скидки");return;}offers.add(new Offer(store,type,n,val==null?0:val,minimum==null?0:minimum,offerExpiry.getText().toString().trim(),offerSource.getText().toString().trim(),offerStackable.isChecked()));offerName.setText("");offerValue.setText("");offerMinimum.setText("");offerExpiry.setText("");offerSource.setText("");offerStackable.setChecked(false);save();renderLists();recalculate();}
    private void renderLists(){if(productList==null||offerList==null)return;productList.removeAllViews();offerList.removeAllViews();for(int i=0;i<products.size();i++){final int ix=i;Product p=products.get(i);LinearLayout c=card();LinearLayout h=row();h.addView(label(p.name+" ×"+p.qty,15,INK,true),new LinearLayout.LayoutParams(0,-2,1));Button rm=small("Убрать");h.addView(rm);rm.setOnClickListener(v->{products.remove(ix);save();renderLists();recalculate();});c.addView(h);c.addView(label("Лента: "+priceText(p.lenta)+"   ·   Ярче!: "+priceText(p.yarche),13,MUTED,false));productList.addView(c);}
        for(int i=0;i<offers.size();i++){final int ix=i;Offer o=offers.get(i);LinearLayout c=card();LinearLayout h=row();h.addView(label((o.store.equals("lenta")?"Лента · ":"Ярче! · ")+o.name,14,INK,true),new LinearLayout.LayoutParams(0,-2,1));Button rm=small("Убрать");h.addView(rm);rm.setOnClickListener(v->{offers.remove(ix);save();renderLists();recalculate();});c.addView(h);String d=o.type.equals("delivery")?"Бесплатная доставка":o.type.equals("percent")?fmt(o.value)+"% от заказа":money(o.value)+" скидки";if(o.minimum>0)d+=" · от "+money(o.minimum);if(!o.expiry.isEmpty())d+=" · до "+o.expiry;if(o.stack)d+=" · совместима";c.addView(label(d,12,MUTED,false));if(!o.source.isEmpty()){TextView src=label("Открыть источник",12,GREEN,false);src.setOnClickListener(v->open(o.source));c.addView(src);}offerList.addView(c);}}
    private void recalculate(){if(results==null)return;results.removeAllViews();if(products.isEmpty()){results.addView(label("Добавьте товары, чтобы сравнить итоговые суммы.",14,MUTED,false));return;}Summary l=calc("lenta",number(lentaDelivery)),y=calc("yarche",number(yarcheDelivery));boolean done=l.total!=null&&y.total!=null;summaryCard("Лента",l,done&&l.total<=y.total);summaryCard("Ярче!",y,done&&y.total<l.total);if(!done)results.addView(label("Для сравнения укажите цены всех товаров и доставку в обоих магазинах. Бесплатная доставка по добавленной акции учтётся без цены доставки.",12,MUTED,false));}
    private Summary calc(String store,Double shipInput){double sub=0;boolean all=true;for(Product p:products){Double v=store.equals("lenta")?p.lenta:p.yarche;if(v==null)all=false;else sub+=v*p.qty;}ArrayList<Offer> eligible=new ArrayList<>();for(Offer o:offers)if(o.store.equals(store)&&sub>=o.minimum&&!expired(o.expiry))eligible.add(o);double best=0;Offer discountOffer=null;for(Offer o:eligible)if(!o.type.equals("delivery")){double d=o.type.equals("percent")?sub*o.value/100:o.value;d=Math.min(sub,d);if(d>best){best=d;discountOffer=o;}}double ship=shipInput==null?0:shipInput;boolean free=false;ArrayList<Offer> applied=new ArrayList<>();if(discountOffer!=null)applied.add(discountOffer);for(Offer o:eligible)if(o.type.equals("delivery")&&(discountOffer==null||(o.stack&&discountOffer.stack))){free=true;applied.add(o);break;}Double total=all&&(shipInput!=null||free)?Math.max(0,sub-best)+(free?0:ship):null;return new Summary(sub,total,free?0:shipInput,best,applied);}
    private boolean expired(String s){if(s==null||s.trim().isEmpty())return false;try{SimpleDateFormat f=new SimpleDateFormat("dd.MM.yyyy",Locale.ROOT);f.setLenient(false);return f.parse(s).before(f.parse(f.format(new Date())));}catch(Exception e){return false;}}
    private void summaryCard(String name,Summary s,boolean win){LinearLayout c=card();if(win)c.setBackground(round(PALE,16));LinearLayout h=row();h.addView(label((win?"✓  ":"")+name,16,win?GREEN:INK,true),new LinearLayout.LayoutParams(0,-2,1));h.addView(label(s.total==null?"—":money(s.total),20,INK,true));c.addView(h);String d="Товары "+money(s.sub)+" · Доставка "+(s.shipping==null?"не указана":money(s.shipping));if(s.discount>0)d+=" · Экономия "+money(s.discount);c.addView(label(d,12,MUTED,false));if(!s.applied.isEmpty()){StringBuilder b=new StringBuilder("Учтено в расчёте: ");for(int i=0;i<s.applied.size();i++){if(i>0)b.append(", ");b.append(s.applied.get(i).name);}c.addView(label(b.toString(),12,GREEN,false));}results.addView(c);}
    private void open(String url){try{startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse(url)));}catch(Exception e){toast("Не удалось открыть ссылку");}}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}private LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(13),dp(10),dp(13),dp(10));l.setBackground(round(Color.WHITE,14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(7);l.setLayoutParams(p);return l;}private LinearLayout.LayoutParams weight(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.rightMargin=dp(7);return p;}private void field(LinearLayout p,View v){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(7);p.addView(v,lp);}private void section(LinearLayout p,String s){TextView t=label(s,17,INK,true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(20);p.addView(t,lp);}private TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(dp(2),dp(4),dp(2),dp(4));return t;}
    private EditText input(String hint,boolean numeric){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(14);e.setPadding(dp(12),0,dp(10),0);e.setHint(hint);e.setBackground(round(Color.WHITE,10));e.setInputType(numeric?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);e.setImeOptions(EditorInfo.IME_ACTION_NEXT);return e;}private Spinner spinner(String[] data){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,data);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);return s;}private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setTextColor(primary?Color.WHITE:GREEN);b.setAllCaps(false);b.setTextSize(14);b.setBackground(round(primary?GREEN:PALE,12));return b;}private Button small(String s){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setTextColor(MUTED);b.setAllCaps(false);b.setMinHeight(dp(32));return b;}private GradientDrawable round(int color,int r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+0.5f);}private Double number(EditText e){try{String s=e.getText().toString().trim().replace(',','.');return s.isEmpty()?null:Double.parseDouble(s);}catch(Exception ex){return null;}}private String money(double d){return NumberFormat.getNumberInstance(new Locale("ru","RU")).format(d)+" ₽";}private String fmt(double d){return NumberFormat.getNumberInstance(Locale.ROOT).format(d);}private String priceText(Double d){return d==null?"—":money(d);}
    private static class Product{String name;Double lenta,yarche;int qty;Product(String n,Double l,Double y,int q){name=n;lenta=l;yarche=y;qty=q;}}private static class Offer{String store,type,name,expiry,source;double value,minimum;boolean stack;Offer(String s,String t,String n,double v,double m,String e,String u,boolean c){store=s;type=t;name=n;value=v;minimum=m;expiry=e;source=u;stack=c;}}private static class Summary{double sub,discount;Double total,shipping;ArrayList<Offer>applied=new ArrayList<>();Summary(double s,Double t,Double h,double d,ArrayList<Offer>a){sub=s;total=t;shipping=h;discount=d;applied=a;}}
}
